pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: any non-contract-ish actor, any positive amount
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract itself with the fuzzed amount
        vm.deal(address(c), amount);

        uint256 callerBefore = actor.balance;

        // drive c through sudicideAnyone as the fuzzed actor
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        assertTrue(ok);

        // RULE: the destroyed contract's entire balance is paid out to the caller.
        assertTrue(actor.balance == callerBefore + amount && address(c).balance == 0);
    }
}

