pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(this), amount);
        // fund the contract so destruction is observable
        (bool okSend, ) = address(c).call{value: amount}("");
        assertTrue(okSend);
        uint256 before = address(c).balance;
        // a caller that is NOT the deployer/owner invokes sudicideAnyone
        vm.assume(actor != msg.sender);
        vm.prank(actor);
        try c.sudicideAnyone() {
            // call succeeded: contract must still hold its ether (owner-gated rule broken by mutant)
            assertTrue(address(c).balance == before, "non-owner call must not destroy the contract");
        } catch {
            // reference reverts for non-owner; contract still holds its ether
            assertTrue(address(c).balance == before, "reverted call must not destroy the contract");
        }
    }
}
